paths.smile='M8 14s1.5 3 4 3 4-3 4-3M8 9h.01M16 9h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0';paths.send='m5 12 7-7 7 7M12 5v15';paths.clock='M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0';
let inlineReactionPost=null,fullEmoji=false,emojiTarget=null,commentDrafts={},reportView='summary';
const startedAt=Date.now();let profilePhotoDraft=null,contactPhotoDraft=null,contactUseProfile=true;
function friendlyTime(value,now=Date.now()){const date=new Date(value),delta=Math.max(0,now-date.getTime()),minutes=Math.floor(delta/60000);if(minutes<1)return 'Just now';if(minutes<60)return minutes+' minute'+(minutes===1?'':'s')+' ago';const hours=Math.floor(minutes/60);if(hours<6)return hours===1?'An hour ago':hours+' hours ago';const today=new Date(now),yesterday=new Date(now);yesterday.setDate(today.getDate()-1);const time=new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(date);if(date.toDateString()===today.toDateString())return 'Today, '+time;if(date.toDateString()===yesterday.toDateString())return 'Yesterday, '+time;return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',...(date.getFullYear()!==today.getFullYear()?{year:'numeric'}:{})}).format(date)}
function timeMarkup(value){const exact=new Intl.DateTimeFormat(undefined,{dateStyle:'full',timeStyle:'short'}).format(new Date(value));return `<button class="post-time" data-exact-time="${escapeHtml(exact)}" title="${escapeHtml(exact)}" aria-label="${escapeHtml(exact)}"><time datetime="${new Date(value).toISOString()}">${friendlyTime(value)}</time><span class="exact-time">${escapeHtml(exact)}</span></button>`}
function avatarMarkup(src,name,extra=''){return src?`<img class="avatar ${extra}" src="${escapeHtml(src)}" alt="${escapeHtml(name)}">`:`<span class="avatar ${extra}">${escapeHtml(name.slice(0,1))}</span>`}
function productCopy(html){return html.replace(previewNotice,'').replace(/<p[^>]*>[^<]*(?:Session-only|Preview only|No purchase|Sample photography for|Preview saved|No money was|No real contributions)[^<]*<\/p>/gi,'').replace(/<span class="badge">(?:Sample[^<]*|Preview[^<]*|Demo[^<]*|Illustrative layout|Admin \/ moderator preview)<\/span>/gi,'').replace(/Session-only preview post/g,'Just now').replace(/Admin \/ moderator preview/g,'For family planners').replace(/Planner preview · sample data/g,'Planner tools').replace(/Family only · sample feed/g,'Family only').replace(/Sample photo post/g,'Yesterday').replace(/Sample poll · Pick one/g,'Yesterday').replace(/Profile preview/g,'Green & White family').replace(/Your preview household/g,'Your household').replace(/Your preview shirts/g,'Shirts selected').replace(/Preview attendees/g,'Attendees').replace(/My contributions|Your contribution|Your contributions/g,'My fees').replace(/Contributions/g,'Fees').replace(/Save preview /g,'Save ').replace(/Post in preview/g,'Post').replace(/Preview “I’ve sent it”/g,'I’ve sent it').replace(/Choose your family shirts/g,'Choose your family shirts').replace(/ · concept design|Concept design/g,'').replace(/Preview schedule/g,'Schedule').replace(/One preview vote per family member\./g,'One vote per person.').replace(/Sample results · Your choice stays in this preview\./g,'Your vote is counted.').replace(/Nothing confirmed yet/g,'No fees confirmed').replace(/Demo review complete · no funds verified/g,'Review complete').replace(/Awaiting confirmation · demo report only/g,'Awaiting confirmation')}
const renderBeforeReview=render;render=function(){renderBeforeReview();$('#main').innerHTML=productCopy($('#main').innerHTML);const profile=$('#profile-popout');if(profile)profile.innerHTML=productCopy(profile.innerHTML);$('#close').innerHTML=icon('close');updateAvatarButtons();};
function updateAvatarButtons(){const trigger=$('#profile-toggle');if(trigger)trigger.innerHTML=preview.profile.photo?`<img src="${escapeHtml(preview.profile.photo)}" alt="">`:escapeHtml(preview.profile.name.slice(0,1))}
const toastBeforeReview=toast;toast=function(text){toastBeforeReview(text.replace(/ in this preview only\.| in preview\.| for this session\.| in the demo\./g,'.').replace('Reaction updated in preview.','Reaction updated.').replace('Private contact preview saved for this session.','Contact card saved.'))};
modal=function(title,html){const sheet=$('#sheet');sheet.classList.remove('focus-surface','composer-surface');delete sheet.dataset.postId;$('#sheet-title').textContent=title.replace(/preview|demo/gi,'').trim();$('#sheet-body').innerHTML=productCopy(html);$('#close').innerHTML=icon('close');if(!sheet.open)sheet.showModal()};
const closeBeforeReview=close;close=function(){captureCommentDraft();closeBeforeReview();$('#sheet').classList.remove('focus-surface','composer-surface');delete $('#sheet').dataset.postId;emojiTarget=null;$('#emoji-popout')?.hidePopover?.()};
function captureCommentDraft(){const el=$('#comment-text');if(el&&$('#sheet').dataset.postId)commentDrafts[activePost]=el.value}
function inlineReactions(id){return `<div class="inline-reactions" aria-label="Choose a reaction"><div class="quick-emoji">${['❤️','👏','😂','🎉','🙏'].map(e=>`<button data-reaction-post="${id}" data-emoji="${e}" aria-label="React ${e}" aria-pressed="${(preview.reactions[id]||[]).includes(e)}">${e}</button>`).join('')}<button class="icon-button" data-all-reactions="${id}" aria-label="More emoji">${icon('plus')}</button></div>${fullEmoji?'<label class="sr-only" for="emoji-search">Find emoji</label><input id="emoji-search" type="search" placeholder="Find an emoji…"><div id="emoji-results"></div>':''}</div>`}
function feedPreviewGroups(id,comments){return comments.filter(c=>!c.parent).slice(-2).map(parent=>{const replies=comments.filter(c=>c.parent===parent.id).slice(-1);return `<div class="feed-preview-thread"><div class="feed-comment">${commentIdentity(parent)}<button data-comment-post="${id}" class="feed-comment-text">${escapeHtml(parent.text.slice(0,180))}</button></div>${replies.map(child=>`<div class="feed-comment feed-reply" aria-label="Reply to ${escapeHtml(parent.name)}">${commentIdentity(child)}<button data-comment-post="${id}" class="feed-comment-text">${escapeHtml(child.text.slice(0,180))}</button></div>`).join('')}</div>`}).join('')}
postActions=function(id,photos=false,detail=false){const reactions=preview.reactions[id]||[],comments=preview.comments[id]||[],count=comments.length;return `<div class="post-actions"><button class="reaction-summary" data-react-post="${id}" aria-expanded="${inlineReactionPost===id}" aria-label="${reactions.length?'Change reactions':'React'}">${reactions.length?`<span class="reaction-faces">${reactions.slice(0,3).join('')}</span><span>${reactions.length}</span>`:icon('heart')+'React'}</button><button data-comment-post="${id}">${icon('chat')}${count?count+' comment'+(count===1?'':'s'):'Comment'}</button>${photos?`<button data-action="memories">${icon('image')}Photos</button>`:''}</div>${inlineReactionPost===id?inlineReactions(id):''}${!detail&&count?`<div class="feed-comments">${feedPreviewGroups(id,comments)}</div>`:''}`};
function refreshPostSurface(){captureCommentDraft();const detail=$('#sheet').dataset.postId;if(detail)showComments(detail,replyParent,false);else render();if(inlineReactionPost&&fullEmoji)renderEmojiResults()}
showReactions=function(id){if(!knownPost(id))return;inlineReactionPost=inlineReactionPost===id?null:id;activePost=id;fullEmoji=false;emojiTarget=null;refreshPostSurface()};
renderEmojiResults=function(){const container=emojiTarget?$('#insertion-emoji-results'):$('#emoji-results');if(!container)return;const matches=emojiChoices().filter(e=>!emojiQuery||e.search.includes(emojiQuery)||e.native.includes(emojiQuery));const shown=matches.slice(0,80*(emojiPage+1));container.innerHTML=`<div class="emoji-grid">${shown.map(e=>`<button aria-label="${escapeHtml(e.name)}" title="${escapeHtml(e.name)}" ${emojiTarget?'data-insert-emoji':'data-emoji'}="${escapeHtml(e.native)}" ${emojiTarget?'':`data-reaction-post="${activePost}"`}>${escapeHtml(e.native)}</button>`).join('')}</div>${shown.length<matches.length?'<button class="text-button" data-review-more-emoji>More emoji</button>':''}`};
function openInsertEmoji(target,button){emojiTarget=target;emojiQuery='';emojiPage=0;const input=$('#'+target);if(input)input.dataset.insertAt=String(input.selectionStart??input.value.length);const panel=$('#emoji-popout');panel.innerHTML='<label class="sr-only" for="insertion-emoji-search">Find emoji</label><input id="insertion-emoji-search" type="search" placeholder="Find an emoji…"><div id="insertion-emoji-results"></div>';panel.showPopover();const r=button.getBoundingClientRect();panel.style.left=Math.max(12,Math.min(r.left,window.innerWidth-324))+'px';panel.style.top=Math.max(12,Math.min(r.bottom+8,window.innerHeight-360))+'px';renderEmojiResults()}
function writingBox(id,value,kind){return `<div class="writing-row"><button class="icon-button emoji-button" type="button" data-emoji-target="${id}" aria-label="Add emoji">${icon('smile')}</button><div class="writing-box ${kind}"><textarea id="${id}" rows="${kind==='comment-writing'?1:5}" maxlength="${kind==='comment-writing'?1500:3000}" placeholder="${kind==='comment-writing'?'Add a comment…':'What’s on your mind?'}">${escapeHtml(value)}</textarea><button type="submit" class="send-button" aria-label="${kind==='comment-writing'?'Send comment':'Post'}">${icon('send')}</button></div></div>`}
const addCommentBeforeReview=addComment;addComment=function(id,text,parent=null){const ok=addCommentBeforeReview(id,text,parent);if(ok){preview.comments[id].at(-1).createdAt=Date.now();preview.comments[id].at(-1).memberId='self';}return ok};
commentTree=function(id){const comments=preview.comments[id]||[];return comments.map(c=>{const parent=comments.find(x=>x.id===c.parent);return `<article class="chat-message"><div class="message-meta">${commentIdentity(c)}${timeMarkup(c.createdAt||startedAt)}</div><div class="chat-bubble">${parent?`<div class="quoted-reply"><strong>${escapeHtml(parent.name)}</strong><span>${escapeHtml(parent.text.slice(0,100))}</span></div>`:''}<p>${escapeHtml(c.text)}</p></div><button class="text-button reply-button" data-reply-id="${c.id}">Reply</button></article>`}).join('')};
function postDetail(id){const p=preview.posts.find(x=>x.id===id);if(p)return `<div class="row post-head">${avatarMarkup(preview.profile.photo,p.name)}<div><strong>${escapeHtml(p.name)}</strong>${timeMarkup(p.createdAt||startedAt)}</div></div><p class="preview-prose">${escapeHtml(p.text)}</p>${p.attachment?attachmentHtml(p.attachment):''}${postMedia(p)}`;if(id==='photo')return `${postHead('The planning crew','Yesterday')}<h2>It starts with our people.</h2><p class="muted">A place for all our favorite moments.</p><img class="photo section-gap" src="${familyPhotos.generations}" alt="Three generations together">`;return `${postHead('The planning crew','Yesterday')}<h2>What’s on the reunion playlist?</h2><div class="poll" role="radiogroup" aria-label="Choose one option">${['The classics','A little bit of everything','Let the cousins DJ'].map((x,i)=>`<button data-vote="${i}" role="radio" aria-checked="${vote===String(i)}">${escapeHtml(x)}<span class="poll-indicator ${vote===String(i)?'selected':''}">${vote===String(i)?icon('check'):''}</span></button>`).join('')}</div>`}
showComments=function(id,parent=null,focus=true){if(!knownPost(id))return;captureCommentDraft();activePost=id;replyParent=parent;const target=(preview.comments[id]||[]).find(x=>x.id===parent);modal('Family conversation',`<article class="focused-post">${postDetail(id)}${postActions(id,false,true)}</article><div class="comments-list chat-thread">${commentTree(id)||'<p class="muted empty-conversation">Be the first to say something.</p>'}</div><form id="comment-form" class="conversation-composer">${target?`<div class="replying-to">Replying to ${escapeHtml(target.name)}<button type="button" class="text-button" data-preview-action="cancel-reply">Cancel</button></div>`:''}${writingBox('comment-text',commentDrafts[id]||'','comment-writing')}<p id="comment-error" class="form-error" role="alert"></p></form>`);$('#sheet').classList.add('focus-surface');$('#sheet').dataset.postId=id;if(focus)$('#comment-text')?.focus?.();if(fullEmoji)renderEmojiResults()};
showComposer=function(){modal('Post to the family',`<form id="composer-form">${composerExtras()}${writingBox('post-text',composer.text,'post-writing')}<div id="composer-attachment">${composerAttachment()}</div><p class="form-error" id="composer-error" role="alert"></p></form>`);$('#sheet').classList.add('composer-surface')};
composerExtras=function(){return `<div class="attachment-actions"><label class="text-button" for="post-photos">${icon('image')}Upload media</label><input id="post-photos" class="visually-hidden" type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple><button type="button" class="text-button" data-preview-action="toggle-poll">${icon('chat')}${composer.poll?'Remove poll':'Create poll'}</button></div><div id="post-photo-previews">${photoDraftHtml()}</div>${composer.poll?`<div class="poll-draft"><label for="poll-question">Your question</label><input id="poll-question" maxlength="160" value="${escapeHtml(composer.poll.question)}"><label for="poll-options">Choices · one per line</label><textarea id="poll-options" maxlength="600" rows="3">${escapeHtml(composer.poll.options.join('\n'))}</textarea></div>`:''}`};
attachmentHtml=function(a){return `<div class="link-preview">${icon(a.provider==='Link'?'arrow':'image')}<div><strong>${escapeHtml(a.provider==='Link'?a.host:a.provider)}</strong><p><a href="${escapeHtml(a.href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(a.host)}</a></p></div></div>`};
const publishBeforeReview=publishPreviewPost;publishPreviewPost=function(){const ok=publishBeforeReview();if(ok){preview.posts[0].createdAt=Date.now();render()}return ok};
const saveBeforeReview=savePreviewForm;savePreviewForm=function(id){if(id==='comment-form')commentDrafts[activePost]='';const result=saveBeforeReview(id);return result};
const homeBeforeReview=home;home=function(){let html=homeBeforeReview();for(const p of preview.posts){html=html.replace(postHead(escapeHtml(p.name),'Session-only preview post',escapeHtml(p.name.slice(0,1))),`<div class="row post-head">${avatarMarkup(preview.profile.photo,p.name)}<div><strong>${escapeHtml(p.name)}</strong>${timeMarkup(p.createdAt||startedAt)}</div></div>`)}return html};
function autoGrow(input){input.style.height='auto';input.style.height=Math.min(input.scrollHeight,180)+'px'}
$('#sheet').addEventListener('click',e=>{if(e.target!==$('#sheet'))return;const r=$('#sheet').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){e.preventDefault();close()}});
$('#close').onclick=()=>close();
document.addEventListener('input',e=>{if(e.target.id==='comment-text'){commentDrafts[activePost]=e.target.value;autoGrow(e.target)}if(e.target.id==='insertion-emoji-search'){emojiQuery=e.target.value.trim().toLowerCase();emojiPage=0;renderEmojiResults()}},true);
document.addEventListener('click',e=>{const target=e.target.closest('[data-emoji-target]');if(target){e.preventDefault();e.stopImmediatePropagation();openInsertEmoji(target.dataset.emojiTarget,target);return}const insert=e.target.closest('[data-insert-emoji]');if(insert){e.preventDefault();e.stopImmediatePropagation();const input=$('#'+emojiTarget);if(input){const at=Number(input.dataset.insertAt||input.value.length);input.value=input.value.slice(0,at)+insert.dataset.insertEmoji+input.value.slice(at);input.dataset.insertAt=String(at+insert.dataset.insertEmoji.length);if(emojiTarget==='post-text')composer.text=input.value;else{commentDrafts[activePost]=input.value;autoGrow(input)}input.focus()}$('#emoji-popout').hidePopover();return}const more=e.target.closest('[data-all-reactions]');if(more){e.preventDefault();e.stopImmediatePropagation();fullEmoji=!fullEmoji;emojiTarget=null;activePost=more.dataset.allReactions;emojiQuery='';emojiPage=0;refreshPostSurface();return}if(e.target.closest('[data-review-more-emoji]')){e.preventDefault();e.stopImmediatePropagation();emojiPage++;renderEmojiResults();return}const react=e.target.closest('[data-reaction-post]');if(react){e.preventDefault();e.stopImmediatePropagation();toggleReaction(react.dataset.reactionPost,react.dataset.emoji);refreshPostSurface();return}const exact=e.target.closest('[data-exact-time]');if(exact){exact.classList.toggle('show-exact');return}},true);
render();refreshWordmark();
function photoEditor(kind,src,name){return `<div class="photo-editor"><div id="${kind}-photo-preview">${avatarMarkup(src,name,'large-avatar')}</div><label class="text-button" for="${kind}-photo">${icon('image')}${src?'Change photo':'Add photo'}</label><input class="visually-hidden" id="${kind}-photo" type="file" accept="image/jpeg,image/png,image/webp,image/avif"></div>`}
showProfile=function(){profilePhotoDraft=preview.profile.photo||null;modal('Edit profile',`<form id="profile-form">${photoEditor('profile',profilePhotoDraft,preview.profile.name)}<label for="profile-name">Name</label><input id="profile-name" maxlength="60" required value="${escapeHtml(preview.profile.name)}"><label for="profile-bio">About you</label><textarea id="profile-bio" rows="3" maxlength="400">${escapeHtml(preview.profile.bio)}</textarea><label for="profile-socials">Social links</label><textarea id="profile-socials" rows="3" maxlength="1600" placeholder="One link per line">${escapeHtml(preview.profile.socials.join('\n'))}</textarea><p id="profile-error" class="form-error" role="alert"></p><button class="button" type="submit">${icon('check')}Save profile</button></form>`)};
showContact=function(){const c=preview.contact||{};contactUseProfile=c.useProfile!==false;contactPhotoDraft=c.photo||null;modal('Your contact card',`<form id="contact-form">${photoEditor('contact',contactUseProfile?preview.profile.photo:contactPhotoDraft,c.name||preview.profile.name)}<label class="member-choice"><input id="contact-use-avatar" type="checkbox" ${contactUseProfile?'checked':''}>Use profile photo</label><label for="contact-name">Name</label><input id="contact-name" maxlength="60" value="${escapeHtml(c.name||preview.profile.name)}"><label for="contact-email">Email</label><input id="contact-email" type="email" maxlength="160" value="${escapeHtml(c.email||'')}"><label for="contact-phone">Phone</label><input id="contact-phone" type="tel" maxlength="40" value="${escapeHtml(c.phone||'')}"><details class="more-information"><summary>More information</summary><label for="contact-address">Address</label><textarea id="contact-address" maxlength="300" rows="2">${escapeHtml(c.address||'')}</textarea><label for="contact-social">Social link</label><input id="contact-social" type="url" value="${escapeHtml(c.social||'')}"><label for="contact-visibility">Who can see your details?</label><select id="contact-visibility">${['Only me','Selected family members','Family leaders','All approved family members'].map(x=>`<option ${x===(c.visibility||'Only me')?'selected':''}>${x}</option>`).join('')}</select></details><label class="member-choice"><input id="contact-optin" type="checkbox" ${c.optIn?'checked':''}>Include my card in the family address book</label><button class="button" type="submit">${icon('check')}Save contact card</button></form>`)};
savePreviewForm=function(id){if(id==='comment-form'){const input=$('#comment-text');if(!addComment(activePost,input.value,replyParent)){$('#comment-error').textContent='Write a comment before sending.';return}input.value='';commentDrafts[activePost]='';render();return showComments(activePost,null,true)}if(id==='profile-form'){const before=preview.profile;saveBeforeReview(id);if(preview.profile!==before){preview.profile.photo=profilePhotoDraft;render()}return}if(id==='contact-form'){const before=preview.contact,address=$('#contact-address').value,social=$('#contact-social').value,visibility=$('#contact-visibility').value;if(social&&!safeUrl(social)){toast('Use a valid web link.');return}saveBeforeReview(id);if(preview.contact!==before){Object.assign(preview.contact,{photo:contactPhotoDraft,useProfile:contactUseProfile,address:address.slice(0,300),social:social?safeUrl(social):'',visibility});}return}return saveBeforeReview(id)};
async function readPersonPhoto(file,kind){if(!file)return;if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)||file.size>8*1024*1024)return toast('Choose a photo under 8 MB.');try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});if(kind==='profile')profilePhotoDraft=src;else{contactPhotoDraft=src;contactUseProfile=false;const toggle=$('#contact-use-avatar');if(toggle)toggle.checked=false}const box=$('#'+kind+'-photo-preview');if(box)box.innerHTML=avatarMarkup(src,preview.profile.name,'large-avatar')}catch{toast('Couldn’t read that photo. Please try another.')}}
const youBeforePhotos=you;you=function(){let html=youBeforePhotos();html=html.replace('<span class="avatar">L</span>',avatarMarkup(preview.profile.photo,preview.profile.name));const old=row('settings','Planner overview','Everything in one place','planner');return html.replace(old,`<button class="planner-entry" data-action="planner"><span class="planner-entry-art">${icon('calendar')}</span><span><strong>Planner overview</strong><span>Your reunion dashboard</span></span>${icon('arrow')}</button>`)};
notifications=function(){const all=[{kind:'leaders',title:'Welcome from the planning crew',body:'Catch up on the latest reunion plans.'},{kind:'family',title:'A new family memory',body:'A new photo has been shared with the family.'}],shown=all.filter(n=>notificationScope==='all'||notificationScope==='leaders'&&n.kind==='leaders'||notificationScope==='family'&&n.kind==='family'||notificationScope==='loved'&&n.kind==='loved'||notificationScope==='selected'&&n.kind==='family'&&selectedPeople.length);const box=$('#notifications-popout');box.innerHTML=`<div class="row spread"><h2>Notifications</h2><button class="icon-button" data-action="notification-settings" aria-label="Notification settings">${icon('settings')}</button></div>${shown.length?shown.map(n=>`<article class="notification-item"><span class="notification-dot ${readNotices?'read':''}"></span><div><strong>${n.title}</strong><p>${n.body}</p></div></article>`).join(''):'<p class="empty">You’re all caught up.</p>'}${shown.length?'<button class="text-button full" data-mark-read>Mark all read</button>':''}`;if(!box.matches(':popover-open'))box.showPopover()};$('#notifications').onclick=notifications;
notificationSettings=function(){modal('Notifications',`<p class="muted">Whose updates would you like?</p><div class="notification-choices">${[['all','All'],['family','Family'],['loved','Loved Ones'],['selected','Selected'],['leaders','Leaders'],['off','Off']].map(([id,label])=>`<button class="list-row" data-notification-scope="${id}" aria-pressed="${notificationScope===id}"><span>${label}</span><span class="arrow">${notificationScope===id?icon('check'):''}</span></button>`).join('')}</div>${notificationScope==='selected'?`<label class="member-choice"><input type="checkbox" data-selected-person="sample-cousin" ${selectedPeople.length?'checked':''}>Family member</label>`:''}`)};
function feeStatus(){const reported=!!preview.contribution;modal('My fees',`<div class="fee-status"><div class="status-illustration">${icon(reported?'clock':'wallet')}</div><h2>${reported?'Awaiting confirmation':'Ready when you are'}</h2><p>${reported?'The treasurer will confirm your payment.':'Your fees will appear once the plans are set.'}</p></div>${!reported?'<button class="button full" data-action="sent-preview">I’ve sent it</button>':''}`)}
const actBeforeFees=act;act=function(a){if(a==='contribute')return feeStatus();if(a==='sent-preview'){preview.contribution='Awaiting confirmation';return feeStatus()}return actBeforeFees(a)};
function reportToggle(){return `<div class="report-toggle"><button data-report-view="summary" aria-pressed="${reportView==='summary'}">${icon('image')}Summary</button><button data-report-view="table" aria-pressed="${reportView==='table'}">${icon('people')}Details</button></div>`}
showShirtTotals=function(){const rows=[{name:'Family order',design:'Forest green',size:'M',quantity:2},...(preview.shirt?[{...preview.shirt,name:'Your household'}]:[])];const total=rows.reduce((n,r)=>n+r.quantity,0);modal('Shirt totals',`${reportToggle()}${reportView==='summary'?`<div class="report-total"><strong>${total}</strong><span>shirts selected</span></div><div class="report-bars">${rows.map(r=>`<div><span>${escapeHtml(r.design)} · ${escapeHtml(r.size)}</span><meter min="0" max="${Math.max(total,1)}" value="${r.quantity}">${r.quantity}</meter><b>${r.quantity}</b></div>`).join('')}</div>`:`<label for="report-filter">Find a household</label><input id="report-filter" type="search" placeholder="Search"><div class="table-scroll"><table><thead><tr><th>Household</th><th>Design</th><th>Size</th><th>Qty</th></tr></thead><tbody>${rows.map(r=>`<tr data-report-row><td>${escapeHtml(r.name)}</td><td>${escapeHtml(r.design)}</td><td>${escapeHtml(r.size)}</td><td>${r.quantity}</td></tr>`).join('')}</tbody></table></div>`}`);$('#sheet').dataset.report='shirts'};
showContributionReview=function(){const pending=preview.contribution?1:0;modal('Family fees',`${reportToggle()}${reportView==='summary'?`<div class="report-total"><strong>${pending}</strong><span>awaiting confirmation</span></div><div class="fee-summary-grid"><div><b>0</b><span>Confirmed</span></div><div><b>${pending}</b><span>Reported</span></div></div><p class="muted">Fee amounts haven’t been set.</p>`:`<div class="table-scroll"><table><thead><tr><th>Household</th><th>Status</th><th>Amount</th></tr></thead><tbody>${pending?'<tr><td>Your household</td><td>Awaiting confirmation</td><td>Not set</td></tr>':'<tr><td colspan="3">No payments reported yet.</td></tr>'}</tbody></table></div>`}`);$('#sheet').dataset.report='fees'};
document.addEventListener('change',e=>{if(e.target.id==='profile-photo')readPersonPhoto(e.target.files[0],'profile');if(e.target.id==='contact-photo')readPersonPhoto(e.target.files[0],'contact');if(e.target.id==='contact-use-avatar'){contactUseProfile=e.target.checked;$('#contact-photo-preview').innerHTML=avatarMarkup(contactUseProfile?preview.profile.photo:contactPhotoDraft,preview.profile.name,'large-avatar')}},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-mark-read]')){e.preventDefault();readNotices=true;notifications()}const report=e.target.closest('[data-report-view]');if(report){reportView=report.dataset.reportView;if($('#sheet').dataset.report==='fees')showContributionReview();else showShirtTotals()}},true);
document.addEventListener('input',e=>{if(e.target.id==='report-filter'){document.querySelectorAll('[data-report-row]').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}},true);
const fitBeforeReview=fitWordmark;fitWordmark=function(){fitBeforeReview();const mark=$('.wordmark'),image=$('.brand>img');if(mark?.getBoundingClientRect&&image){const h=mark.getBoundingClientRect().height;image.style.height=h+'px';image.style.width=(h*1.72)+'px'}};
render();refreshWordmark();
const familyBeforeReview=family;family=function(){let html=familyBeforeReview();const c=preview.contact;if(c&&familyTab==='people'){const photo=c.useProfile!==false?preview.profile.photo:c.photo;html=html.replace(/<div class="directory-empty">[\s\S]*?<\/div>/,`<div class="contact-card-saved">${avatarMarkup(photo,c.name||preview.profile.name,'large-avatar')}<h3>${escapeHtml(c.name||preview.profile.name)}</h3>${c.email?`<p>${escapeHtml(c.email)}</p>`:''}${c.phone?`<p>${escapeHtml(c.phone)}</p>`:''}<span class="badge">${c.optIn?'Your family card':'Only you'}</span>${button('Edit my card','contact-card',true)}</div>`)}return html};
const copyBeforeFinal=productCopy;productCopy=function(html){return copyBeforeFinal(html).replace(/<(p|div|span)[^>]*class="[^\"]*\b(?:note|preview-footer)\b[^\"]*"[^>]*>[\s\S]*?<\/\1>/gi,'').replace(/<p[^>]*>[^<]*(?:preview|demo|sample|session.only|prototype)[^<]*<\/p>/gi,'').replace(/\b(?:Preview|Demo|Sample)\s+(?:setup|status|results|report|sizes|ordering worksheet)/g,'').replace(/Preview setup/g,'Payment settings').replace(/Preview only/g,'').replace(/in this preview/g,'').replace(/Sample household/g,'Family household')};
const renderAfterCopy=render;render=function(){renderAfterCopy();const panel=$('#profile-popout');if(panel){panel.innerHTML=productCopy(panel.innerHTML);if(!panel.querySelector?.('[data-platform-style]'))panel.innerHTML+=`<div class="platform-preference"><label for="platform-style">App style</label><select id="platform-style" data-platform-style><option value="standard" ${document.documentElement.dataset.platformStyle!=='glass'?'selected':''}>Original</option><option value="glass" ${document.documentElement.dataset.platformStyle==='glass'?'selected':''}>Glass</option></select></div>`}};
try{const chosen=localStorage.getItem('gw-platform-style'),ua=navigator.userAgent||'',isApple=/iPhone|iPad|iPod/.test(ua)||/Macintosh/.test(ua)&&navigator.maxTouchPoints>1;document.documentElement.dataset.platformStyle=chosen||(isApple?'glass':'standard')}catch{}
document.addEventListener('change',e=>{if(e.target.id==='platform-style'){document.documentElement.dataset.platformStyle=e.target.value;remember('gw-platform-style',e.target.value)}},true);
const refreshProfileBefore=renderProfile;renderProfile=function(){refreshProfileBefore();const panel=$('#profile-popout');panel.innerHTML+=`<div class="platform-preference"><label for="platform-style">App style</label><select id="platform-style" data-platform-style><option value="standard" ${document.documentElement.dataset.platformStyle!=='glass'?'selected':''}>Original</option><option value="glass" ${document.documentElement.dataset.platformStyle==='glass'?'selected':''}>Glass</option></select></div>`};
render();refreshWordmark();
$('#sheet').addEventListener('cancel',e=>{e.preventDefault();close()});
const timedHome=home;home=function(){return timedHome().replace(postHead('The planning crew','Sample photo post'),`<div class="row post-head"><span class="avatar">GW</span><div><strong>The planning crew</strong>${timeMarkup(startedAt-86400000)}</div></div>`).replace(postHead('A little family vote','Sample poll · Pick one'),`<div class="row post-head"><span class="avatar">GW</span><div><strong>The planning crew</strong>${timeMarkup(startedAt-172800000)}</div></div>`)};
// Keep sensitive contact information in memory; external services stay disconnected.
render();refreshWordmark();

const commentMembers=new Map();let profileReturnPost=null;
function commentMember(c){const id=c.memberId||(c.name===preview.profile.name?'self':c.id);const person=id==='self'?{id,name:preview.profile.name,photo:preview.profile.photo,bio:preview.profile.bio,socials:preview.profile.socials}:{id,name:c.name,photo:c.photo||null,bio:c.bio||'',socials:[]};commentMembers.set(id,person);return person}
function commentIdentity(c){const p=commentMember(c);return `<button type="button" class="comment-identity" data-member-card="${escapeHtml(p.id)}" aria-label="View ${escapeHtml(p.name)}'s profile card">${avatarMarkup(p.photo,p.name)}<strong>${escapeHtml(p.name)}</strong></button>`}
function membershipChips(person){const m=person?.membership;if(!m)return '';const circle=m.circle==='loved'?'Loved Ones':m.circle==='family'?'Family':'';return `<div class="membership-chips">${circle?`<span class="membership-chip">${icon(m.circle==='loved'?'heart':'people')}${circle}</span>`:''}${m.groupName?`<button type="button" class="membership-chip" data-group-profile="${escapeHtml(m.groupName)}" aria-label="View ${escapeHtml(m.groupName)} group profile">${icon('home')}${escapeHtml(m.groupName)}</button>`:''}${m.leader?'<span class="membership-chip membership-shield" role="img" aria-label="Family leader" title="Family leader"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 19 6v5c0 5-3 8-7 10-4-2-7-5-7-10V6z M8.5 11.8l2.3 2.3 4.7-4.7"/></svg></span>':''}</div>`}
function showMemberCard(id,anchor){const p=id==='self'?{id,...preview.profile}:commentMembers.get(id);if(!p)return;const panel=$('#member-popout');const host=$('#sheet').open?$('#sheet'):document.body;host.appendChild(panel);panel.innerHTML=`<div class="member-id-head">${avatarMarkup(p.photo,p.name)}<div><strong>${escapeHtml(p.name)}</strong>${membershipChips(p)}</div></div>${p.bio?`<p>${escapeHtml(p.bio)}</p>`:''}<button class="button full" data-member-profile="${escapeHtml(id)}">${icon('user')}View profile</button>`;panel.showPopover();const r=anchor.getBoundingClientRect();panel.style.left=Math.max(12,Math.min(r.left,window.innerWidth-292))+'px';panel.style.top=Math.max(12,Math.min(r.bottom+8,window.innerHeight-panel.offsetHeight-12))+'px'}
function showMemberProfile(id){const p=id==='self'?{id,...preview.profile}:commentMembers.get(id);if(!p)return;captureCommentDraft();profileReturnPost=$('#sheet').dataset.postId||null;$('#member-popout').hidePopover();modal(p.name,`${profileReturnPost?'<button class="back-button" data-member-back>← Back to conversation</button>':''}<section class="member-full-profile">${avatarMarkup(p.photo,p.name)}<h2>${escapeHtml(p.name)}</h2><p>${escapeHtml(p.bio||'Family member')}</p>${membershipChips(p)}<div class="profile-social-links">${(p.socials||[]).map(url=>/^https?:/.test(url)?`<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(new URL(url).hostname)}</a>`:'').join('')}</div></section>`);$('#sheet').classList.add('focus-surface')}
document.addEventListener('click',e=>{const card=e.target.closest('[data-member-card]');if(card){e.preventDefault();e.stopImmediatePropagation();showMemberCard(card.dataset.memberCard,card);return}const profile=e.target.closest('[data-member-profile]');if(profile){e.preventDefault();e.stopImmediatePropagation();showMemberProfile(profile.dataset.memberProfile);return}if(e.target.closest('[data-member-back]')){e.preventDefault();e.stopImmediatePropagation();if(profileReturnPost)showComments(profileReturnPost,null,false)}},true);
// Safari can retain a focus ring on the programmatically focused page surface after a tap.
document.addEventListener('pointerdown',()=>{document.documentElement.dataset.inputMode='pointer'},true);
document.addEventListener('keydown',e=>{if(e.key==='Tab'||e.key.startsWith('Arrow'))document.documentElement.dataset.inputMode='keyboard'},true);
